// Cardiac insight index — record JAH-GAI-ECGMONITOR-000001
// Property of Justin Addam Higgins (JAH). Deterministic: same inputs, same output.
var m = {"leads": 6, "battery_months": 6, "price_usd": 150};
var value = (m.leads*m.battery_months/m.price_usd*100);
if (!isFinite(value)) { console.log('DEMO_FAIL|JAH-GAI-ECGMONITOR-000001|non-finite'); process.exit(1); }
console.log('DEMO_OK|JAH-GAI-ECGMONITOR-000001|' + value.toFixed(2) + ' insight index');

